"use client";
// The narrated guided visits, told as a story in chapters → beats (data only, generated by scripts/build-tour.mjs):
// "Visite express" (lib/ai/tour-script.json) and "Visite complète" (lib/ai/tour-complete.json).
// ONE VOICE per visit, never mixed:
//   • audio mode — pre-generated narration (public/audio/tour), used ONLY if every beat of the visit exists, from the
//     same model and voice, with a text hash matching the current script;
//   • live mode — otherwise the whole visit is spoken by one browser voice (lib/ai/voices.ts), sentence by sentence,
//     timing driven by the speech "end" events, captions synced per sentence.
// Cursor actions sit on the narration's clock (at = fraction, atSec = seconds, atSentence = when sentence n starts).
// Pause / resume / stop, previous / next chapter, chapter menu; durations from the manifest (audio) or estimated (live).
import express from "./tour-script.json";
import complete from "./tour-complete.json";
import { useApp } from "../store";
import { useAi, type TourMode } from "./ui";
import { audio, duck, resetDuck } from "./audio";
import { perform, type Op } from "./actions";
import { cursorHide, cursorKeep } from "./cursor";
import { musicStart, musicStop, musicPlaying, musicUserOff } from "./music";
import { swell } from "./sfx";
import { frenchVoice, utter, CPS, voiceName } from "./voices";

export type TourAction = Op & { at?: number; atSec?: number; atSentence?: number };
export type Beat = { id: number | string; title: string; text: string; speech?: string; actions: TourAction[] };
export type Chapter = { id: string; title: string; beats: Beat[] };
type Script = { chapters?: Chapter[]; beats?: Beat[] };
export type { TourMode };

const GAP = 0.6; // pause between beats (s)
export type Timeline = { total: number; beats: { start: number; dur: number }[]; chapters: { start: number; dur: number; title: string; first: number }[] };
type Tour = { chapters: Chapter[]; beats: (Beat & { chapter: number })[]; timeline: Timeline; plan: "audio" | "live" };
const mk = (s: Script): Tour => {
  const chapters = s.chapters ?? [{ id: "tour", title: "Visite guidée", beats: s.beats ?? [] }];
  return { chapters, beats: chapters.flatMap((c, ci) => c.beats.map((b) => ({ ...b, chapter: ci }))), timeline: { total: 0, beats: [], chapters: [] }, plan: "live" };
};
export const TOURS: Record<TourMode, Tour> = { express: mk(express as unknown as Script), complete: mk(complete as unknown as Script) };
export const MODE_LABEL: Record<TourMode, string> = { express: "Visite express", complete: "Visite complète" };

const said = (b: Beat) => b.speech || b.text;
const sentences = (t: string) => t.match(/[^.!?…]+[.!?…]+["»”]?\s*|[^.!?…]+$/g)?.map((s) => s.trim()).filter(Boolean) ?? [t];

// ---------------------------------------------------------------- narration manifest and the audio-or-live decision
type Manifest = { voice?: string; beats: Record<string, { file: string; duration: number; hash?: string; model?: string; voice?: string }> };
let manifest: Manifest | null = null;
let ready: Promise<void> | null = null;
const buffers = new Map<string, Promise<AudioBuffer | null>>();

async function sha1(s: string) {
  const d = await crypto.subtle.digest("SHA-1", new TextEncoder().encode(s));
  return [...new Uint8Array(d)].map((x) => x.toString(16).padStart(2, "0")).join("");
}
/** Audio only if EVERY beat exists, same model, same voice, hash of the current text: otherwise live for the whole visit. */
async function planFor(t: Tour): Promise<"audio" | "live"> {
  const m = manifest;
  if (!m?.voice || typeof crypto === "undefined" || !crypto.subtle) return "live";
  const models = new Set<string>();
  for (const b of t.beats) {
    const e = m.beats[String(b.id)];
    if (!e?.file || !e.hash || !e.model) return "live";
    if ((e.voice ?? m.voice) !== m.voice) return "live";
    models.add(e.model);
    if ((await sha1(m.voice + "|" + said(b))).slice(0, 12) !== e.hash) return "live";
  }
  return models.size === 1 ? "audio" : "live";
}
export function loadManifest() {
  if (!ready) ready = (async () => {
    try { manifest = await (await fetch("/audio/tour/manifest.json", { cache: "no-cache" })).json(); } catch { manifest = { beats: {} }; }
    for (const mode of Object.keys(TOURS) as TourMode[]) { TOURS[mode].plan = await planFor(TOURS[mode]).catch(() => "live" as const); computeTimeline(mode); }
  })();
  return ready;
}
function loadBeat(t: Tour, i: number): Promise<AudioBuffer | null> {
  const b = t.beats[i];
  if (!b || t.plan !== "audio") return Promise.resolve(null);
  const key = String(b.id);
  if (!buffers.has(key)) {
    buffers.set(key, (async () => {
      const e = manifest?.beats[key];
      if (!e?.file) return null;
      try { return await audio().ctx.decodeAudioData(await (await fetch(`/audio/tour/${e.file}?v=${e.hash ?? ""}`)).arrayBuffer()); } catch { return null; }
    })());
  }
  return buffers.get(key)!;
}

// ---------------------------------------------------------------- timelines
const estimate = (b: Beat) => Math.max(3, said(b).length / CPS);
function computeTimeline(mode: TourMode) {
  const T = TOURS[mode];
  let t = 0;
  const beats = T.beats.map((b) => {
    const dur = T.plan === "audio" ? manifest?.beats[String(b.id)]?.duration ?? estimate(b) : estimate(b);
    const r = { start: t, dur };
    t += dur + GAP;
    return r;
  });
  const chapters = T.chapters.map((c, ci) => {
    const first = T.beats.findIndex((b) => b.chapter === ci);
    const last = T.beats.map((b) => b.chapter).lastIndexOf(ci);
    const start = beats[first]?.start ?? 0;
    const end = (beats[last]?.start ?? 0) + (beats[last]?.dur ?? 0) + GAP;
    return { start, dur: end - start, title: c.title, first };
  });
  T.timeline = { total: t, beats, chapters };
  useAi.getState().set({ tourTotals: { ...useAi.getState().tourTotals, [mode]: t } });
}
(Object.keys(TOURS) as TourMode[]).forEach(computeTimeline);

export const fmtTime = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
/** "4 min 30" under 10 minutes, "12 min" above. */
export const fmtDur = (s: number) => {
  const m = Math.floor(s / 60), r = Math.round(s % 60);
  if (m >= 10) return `${Math.round(s / 60)} min`;
  return r ? `${m} min ${String(r).padStart(2, "0")}` : `${m} min`;
};

class TourPlayer {
  private gen = 0;
  private paused = false;
  private resumeWaiters: (() => void)[] = [];
  private src: AudioBufferSourceNode | null = null;
  private buf: AudioBuffer | null = null;
  private startedAt = 0;   // wall-clock (s) when the beat audio (virtually) started
  private offset = 0;      // elapsed seconds when paused
  private dur = 0;
  private ownsMusic = false; // the tour switched the music on: it fades it out at the end
  // live mode
  private live = false;
  private cum: number[] = [];   // estimated start (s) of each sentence
  private est: number[] = [];   // estimated length (s) of each sentence
  private sentIdx = 0;
  private sentStart = 0;
  private abortUtter: (() => void) | null = null;
  step = 0;
  mode: TourMode = "express";
  get T() { return TOURS[this.mode]; }
  /** "audio" (pre-generated, one voice) or the browser voice used live. */
  narration() { return this.T.plan === "audio" ? "narration enregistrée" : `voix ${voiceName() || "du navigateur"}`; }

  /** Seconds elapsed in the current beat (stops while paused). */
  elapsed() {
    if (this.paused) return this.offset;
    if (this.live) return (this.cum[this.sentIdx] ?? 0) + Math.min(performance.now() / 1000 - this.sentStart, this.est[this.sentIdx] ?? 0);
    return performance.now() / 1000 - this.startedAt;
  }
  position() {
    const b = this.T.timeline.beats[this.step];
    return b ? b.start + Math.min(b.dur, Math.max(0, this.elapsed())) : 0;
  }
  progress() {
    const total = this.T.timeline.total;
    return total ? Math.min(1, this.position() / total) : 0;
  }
  chapter() { return this.T.beats[this.step]?.chapter ?? 0; }

  async start(mode: TourMode = this.mode, from = 0) {
    this.stop(true);
    const my = ++this.gen;
    this.mode = mode;
    audio(); // inside the click
    if (!musicPlaying() && !musicUserOff()) { musicStart(); useApp.getState().setMusicOn(true); this.ownsMusic = true; }
    useApp.getState().setChatOpen(false);
    useAi.getState().set({ tourStatus: "playing", tourMode: mode });
    useApp.getState().setTour({ playing: true, step: from, caption: "" });
    duck(true);
    await Promise.all([loadManifest(), frenchVoice()]);
    if (my !== this.gen) return;
    const T = this.T;
    loadBeat(T, from); loadBeat(T, from + 1);
    for (let i = from; i < T.beats.length; i++) {
      if (my !== this.gen) return;
      await this.playBeat(i, my);
      if (my !== this.gen) return;
      await this.wait(GAP, my);
    }
    if (my !== this.gen) return;
    await this.wait(1.2, my);
    if (my === this.gen) this.stop();
  }

  goChapter(ci: number, mode: TourMode = this.mode) {
    const T = TOURS[mode];
    const c = Math.max(0, Math.min(T.chapters.length - 1, ci));
    const first = T.beats.findIndex((b) => b.chapter === c);
    if (first >= 0) this.start(mode, first);
  }
  next() { if (this.chapter() < this.T.chapters.length - 1) this.goChapter(this.chapter() + 1); }
  prev() {
    const c = this.chapter();
    const into = this.position() - (this.T.timeline.chapters[c]?.start ?? 0);
    this.goChapter(into > 3 || c === 0 ? c : c - 1);
  }

  private async playBeat(i: number, my: number) {
    const T = this.T;
    const beat = T.beats[i];
    const newChapter = i === 0 || T.beats[i - 1]?.chapter !== beat.chapter || this.step !== i - 1;
    this.step = i;
    useApp.getState().setTour({ step: i, playing: true });
    useAi.getState().set({ tourTitle: beat.title, tourChapter: beat.chapter });
    loadBeat(T, i + 1);
    const buf = T.plan === "audio" ? await loadBeat(T, i) : null;
    if (my !== this.gen) return;
    await this.gate(my);
    if (newChapter) swell();

    const caps = sentences(beat.text);
    const spoken = sentences(said(beat));
    const capFor = (k: number) => caps[Math.min(caps.length - 1, Math.round((k * caps.length) / Math.max(1, spoken.length)))];
    // sentence start times, as fractions of the beat (by length): used for captions in audio mode and atSentence
    const lens = spoken.map((s) => s.length);
    const totalLen = lens.reduce((s, l) => s + l, 0) || 1;
    const frac: number[] = []; lens.reduce((acc, l, k) => { frac[k] = acc / totalLen; return acc + l; }, 0);

    this.offset = 0;
    this.live = !buf;
    let speech: Promise<void>;
    if (buf) {
      this.buf = buf;
      this.dur = buf.duration;
      this.startedAt = performance.now() / 1000;
      this.playFrom(0);
      let shown = -1;
      const tick = () => {
        if (my !== this.gen) return;
        const f = Math.min(0.999, this.elapsed() / this.dur);
        let k = 0; while (k + 1 < frac.length && f >= frac[k + 1]) k++;
        if (k !== shown) { shown = k; this.sentIdx = k; useApp.getState().setTour({ caption: capFor(k) }); }
      };
      tick();
      const id = window.setInterval(tick, 120);
      speech = this.until(this.dur, my).then(() => clearInterval(id));
    } else {
      this.buf = null;
      this.est = spoken.map((s) => s.length / CPS);
      this.cum = []; this.est.reduce((acc, e, k) => { this.cum[k] = acc; return acc + e; }, 0);
      this.dur = this.est.reduce((s, e) => s + e, 0);
      speech = (async () => {
        for (let k = 0; k < spoken.length; ) {
          if (my !== this.gen) return;
          await this.gate(my);
          if (my !== this.gen) return;
          this.sentIdx = k; this.sentStart = performance.now() / 1000;
          useApp.getState().setTour({ caption: capFor(k) });
          const ok = await utter(spoken[k], (abort) => { this.abortUtter = abort; });
          this.abortUtter = null;
          if (my !== this.gen) return;
          if (!ok) continue; // paused mid-sentence: say it again after resume
          k++;
        }
        this.sentIdx = spoken.length - 1; this.sentStart = -1e9; // clock at the end of the beat
      })();
    }

    const run = (async () => {
      cursorKeep();
      for (const a of beat.actions) {
        if (my !== this.gen) return;
        if (a.at) await this.until(a.at * this.dur, my);
        if (a.atSec) await this.until(a.atSec, my);
        if (a.atSentence !== undefined) await this.untilSentence(a.atSentence, my);
        await this.gate(my);
        if (my !== this.gen) return;
        const { at, atSec, atSentence, ...op } = a;
        void at; void atSec; void atSentence;
        // running late (slow machine, missing anchor): catch up without the cursor so the film never stalls
        const late = this.elapsed() > this.dur + 1.2;
        await perform((late ? { ...op, silent: true } : op) as Op).catch(() => {});
      }
    })();
    await Promise.all([run, speech]);
  }

  private playFrom(offset: number) {
    const { ctx, voice } = audio();
    if (!this.buf) return;
    const s = ctx.createBufferSource();
    s.buffer = this.buf;
    s.connect(voice);
    if (ctx.state === "suspended") ctx.resume().catch(() => {});
    s.start(ctx.currentTime + 0.02, offset);
    this.startedAt = performance.now() / 1000 + 0.02 - offset;
    this.src = s;
  }
  private stopSource() {
    if (this.src) { try { this.src.stop(); } catch {} this.src.disconnect(); this.src = null; }
  }

  private until(t: number, my: number) {
    return new Promise<void>((resolve) => {
      const tick = () => {
        if (my !== this.gen) return resolve();
        if (!this.paused && this.elapsed() >= t) return resolve();
        window.setTimeout(tick, 60);
      };
      tick();
    });
  }
  private untilSentence(k: number, my: number) {
    return new Promise<void>((resolve) => {
      const tick = () => {
        if (my !== this.gen) return resolve();
        if (!this.paused && this.sentIdx >= k) return resolve();
        window.setTimeout(tick, 50);
      };
      tick();
    });
  }
  private wait(sec: number, my: number) {
    return new Promise<void>((resolve) => {
      let left = sec * 1000;
      let last = performance.now();
      const tick = () => {
        if (my !== this.gen) return resolve();
        const now = performance.now();
        if (!this.paused) left -= now - last;
        last = now;
        if (left <= 0) return resolve();
        window.setTimeout(tick, 50);
      };
      tick();
    });
  }
  private gate(my: number) {
    if (!this.paused || my !== this.gen) return Promise.resolve();
    return new Promise<void>((r) => this.resumeWaiters.push(r));
  }

  pause() {
    if (this.paused || useAi.getState().tourStatus !== "playing") return;
    this.offset = this.elapsed();
    this.paused = true;
    this.stopSource();
    this.abortUtter?.(); // live: the sentence is said again on resume
    useAi.getState().set({ tourStatus: "paused" });
    // store.tour.playing stays true while the tour is active (paused included): other shortcuts read it as "overlay active"
    duck(false);
  }

  resume() {
    if (!this.paused) return;
    audio();
    this.paused = false;
    if (this.live) { this.sentStart = performance.now() / 1000; }
    else if (this.buf && this.offset < this.buf.duration) this.playFrom(this.offset);
    else this.startedAt = performance.now() / 1000 - this.offset;
    useAi.getState().set({ tourStatus: "playing" });
    duck(true);
    const w = this.resumeWaiters.splice(0);
    w.forEach((f) => f());
  }

  toggle(mode?: TourMode) {
    const s = useAi.getState().tourStatus;
    if (s === "idle") this.start(mode ?? this.mode, 0);
    else if (s === "playing") this.pause();
    else this.resume();
  }

  stop(quiet = false) {
    const wasActive = useAi.getState().tourStatus !== "idle";
    this.gen++;
    this.stopSource();
    this.abortUtter?.();
    this.abortUtter = null;
    if (typeof speechSynthesis !== "undefined") speechSynthesis.cancel();
    this.paused = false;
    const w = this.resumeWaiters.splice(0);
    w.forEach((f) => f());
    this.dur = 0;
    if (!quiet || wasActive) {
      if (!quiet) {
        this.step = 0;
        useAi.getState().set({ tourStatus: "idle", tourTitle: "", tourChapter: 0 });
        useApp.getState().setTour({ playing: false, step: 0, caption: "" });
        cursorHide();
      }
      resetDuck();
    }
    if (!quiet && this.ownsMusic) {
      this.ownsMusic = false;
      if (musicPlaying()) { musicStop(); useApp.getState().setMusicOn(false); }
    }
  }
}

export const tour = new TourPlayer();
